// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"proof-of-stake":{"slug":"proof-of-stake","cat":"basics","en":"Proof of stake (PoS)","contentLocale":"en","term":"Proof of stake (PoS)","aka":["PoS"],"short":"Proof of stake (PoS) is a consensus mechanism in which validators lock up the network's coins as collateral to propose and confirm blocks, earning rewards for honest work and losing part of their stake for breaking the rules.","body":[["Instead of competing with electricity like miners, validators put their own coins at risk. The protocol picks validators to propose blocks, and others vote to confirm them. If a ",["validator","validator"]," signs conflicting blocks or tries to cheat, the protocol can destroy part of its stake, a penalty called slashing."],[["Ethereum","ethereum"]," switched to proof of stake in September 2022, cutting its energy use dramatically. Solana, Cardano, Avalanche and many other networks also use variants of PoS. Each sets its own rules for minimum stake, reward rates, lock-up periods and penalties."],["Most holders do not run a validator themselves. They delegate coins to a validator, stake through an exchange earn product, or use a ",["liquid staking","liquid-staking"]," protocol that issues a receipt token. Each route has trade-offs: exchange ",["staking","staking"]," is simple but custodial, while liquid staking adds ",["smart contract","smart-contract"]," risk. Rewards are paid in the same coin, so their value in dollars still moves with the market."]],"example":["Suppose you stake 10 ETH through a provider and the network reward works out to about 3 percent a year, minus a 10 percent commission taken by the provider. Your net rate is 2.7 percent, so after one year you would have about 10.27 ETH. If ETH fell from 3,000 to 2,500 ",["USDT","usdt"]," in that year, your position would be worth about 25,675 USDT instead of the 30,000 USDT you started with, so staking rewards do not protect you from price drops."],"mistakes":["Treating staking rewards as a fixed interest rate when they vary with network activity and the number of stakers.","Ignoring unstaking queues or lock periods and needing the funds urgently.","Forgetting that slashing, provider failures or smart contract bugs can reduce the staked amount."],"faq":[{"q":"Is proof of stake safer than proof of work?","a":"They make different trade-offs. PoW ties security to energy and hardware, while PoS ties it to the value of staked coins that can be slashed. Both have secured large networks for years."},{"q":"Can I lose money staking?","a":"Yes. The coin's price can fall, a validator can be slashed, and a staking provider or smart contract can fail. The reward itself does not guarantee a profit in dollar terms."},{"q":"Which cryptocurrencies use proof of stake?","a":"Ethereum, Solana, Cardano, Avalanche, Polkadot and many others use some form of proof of stake."}],"title":"What is proof of stake (PoS)? Meaning in crypto","description":"Learn how proof of stake works, how validators and slashing keep it secure and what staking means for holders.","related":[["staking","Staking","Staking is locking up coins of a proof-of-stake blockchain to help validate transactions and secure the network, in return for staking rewards paid in that coin."],["liquid-staking","Liquid staking","Liquid staking is a way to stake coins through a protocol that issues a tradable token, such as stETH, representing your staked position, so you earn staking rewards and can still use or sell the token."],["proof-of-work","Proof of work (PoW)","Proof of work (PoW) is a consensus mechanism in which miners use computing power to solve a puzzle, and the first to find a valid answer earns the right to add the next block and collect the reward."],["validator","Validator","A validator is a participant in a proof-of-stake blockchain that locks up coins as collateral and runs software to propose new blocks and vote on whether other blocks are valid."],["ethereum","Ethereum (ETH)","Ethereum is a programmable blockchain that runs smart contracts, and Ether (ETH) is its native coin used to pay gas fees and to stake for network security."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"volatility":{"slug":"volatility","cat":"basics","en":"Volatility","contentLocale":"en","term":"Volatility","aka":["price volatility","vol"],"short":"Volatility is a measure of how much and how quickly an asset's price moves up and down over a given period, and higher volatility means larger, faster swings.","body":[["Crypto is known for high volatility. Daily moves of 3 to 5 percent are common for ",["Bitcoin","bitcoin"],", and small altcoins can move 20 percent or more in a day. ",["Stablecoins","stablecoin"]," are designed to have very low volatility because they track a currency such as the US dollar."],"Traders measure volatility in different ways: the standard deviation of returns, the average true range (ATR) on a chart, or implied volatility from options prices. You do not need the formulas to use the idea. Look at how big a typical daily candle is compared with the price.",["Volatility matters most when you use ",["leverage","leverage"],". A 10 percent move against a 10x position wipes out roughly all of your margin, and ",["liquidation","liquidation"]," can happen before that because of ",["maintenance margin","maintenance-margin"]," and fees. Matching your ",["position size","position-sizing"]," and stop-loss distance to a coin's normal volatility is one of the simplest ways to avoid being stopped out by ordinary noise."]],"example":"Suppose Coin A usually moves about 2 percent a day and Coin B about 8 percent. You want to risk 50 USDT on a trade. If you place your stop just outside a normal day's range, about 3 percent away for Coin A and 12 percent for Coin B, you could open a position of about 1,667 USDT in Coin A but only about 417 USDT in Coin B for the same 50 USDT risk.","mistakes":["Using the same position size and leverage for a calm coin and a wildly volatile one.","Placing stop-losses inside a coin's normal daily range and getting stopped out by noise.","Assuming low volatility will last; quiet periods are often followed by sharp moves."],"faq":[{"q":"Why is crypto so volatile?","a":"Crypto markets trade 24/7, many coins have low liquidity, leverage is widely available and news spreads fast, so prices react quickly and sharply."},{"q":"Is high volatility good or bad?","a":"It cuts both ways. It creates bigger opportunities for traders but also bigger losses, especially with leverage."},{"q":"Which crypto has the lowest volatility?","a":"Stablecoins such as USDT and USDC aim to stay close to 1 US dollar. Among volatile assets, large coins like BTC usually swing less than small altcoins."}],"title":"What is volatility in crypto? Meaning and why it matters","description":"Learn what volatility means, how traders measure it and how to size positions and stop-losses around it.","related":[["leverage","Leverage","Leverage is using borrowed funds or margin to open a position larger than your own capital, which multiplies both profits and losses."],["stop-loss","Stop-loss order","A stop-loss order is an order that automatically closes your position when the price reaches a level you set, limiting how much you can lose on a trade."],["position-sizing","Position sizing","Position sizing is deciding how much to put into a single trade so that, if your stop-loss is hit, you lose only a planned share of your account."],["stablecoin","Stablecoin","A stablecoin is a cryptocurrency designed to keep a steady value, usually 1 US dollar, by being backed by reserves such as cash and treasury bills, by crypto collateral, or by other mechanisms."],["liquidation","Liquidation","Liquidation is when an exchange forcibly closes your leveraged position because your margin has fallen below the maintenance margin requirement."]],"lesson":null,"coin":null,"tool":"/liquidations","cta":false},"stop-limit-order":{"slug":"stop-limit-order","cat":"trading","en":"Stop-limit order","contentLocale":"en","term":"Stop-limit order","aka":["stop limit","stop-limit"],"short":"A stop-limit order combines a stop price and a limit price: when the market reaches the stop price, a limit order is placed at your limit price, so it only fills at that price or better.","body":["You set two prices. The stop price is the trigger. The limit price is the worst price you will accept once triggered. For a sell stop-limit protecting a long position, you might set a stop at 95 and a limit at 94. When the price trades at 95, a sell limit at 94 is placed in the book.",["The advantage over a stop-",["market order","market-order"]," is price control: you will not sell far below your chosen level during a sudden crash. The risk is that the order may not fill at all. If the price gaps from 95 straight to 90, your limit at 94 sits unfilled and your position stays open while losses grow."],["Leave enough room between the stop and limit prices for the coin's normal ",["volatility","volatility"],". Liquid pairs can use a small gap; volatile small coins need more. Exchanges sometimes call these conditional or trigger orders, and their settings can differ, so check how your exchange labels them."]],"example":["Suppose you hold 100 coins bought at 12 ",["USDT","usdt"]," and set a stop-limit with a stop at 10.00 and a limit at 9.90. The price falls to 10.00 and a sell limit for 100 coins at 9.90 is placed. If buyers exist down to 9.90, you sell for about 990 USDT, a loss of roughly 210 USDT. But if bad news drops the price straight to 9.00, your order does not fill, and the position is worth only 900 USDT, a 300 USDT loss, until you act."],"mistakes":["Setting the limit price equal to the stop price, so the order often fails to fill in a fast move.","Using a stop-limit to protect a highly leveraged position where a missed fill can lead to liquidation.","Assuming a triggered stop-limit means the position is closed without checking the open orders."],"faq":[{"q":"What is the difference between a stop-loss and a stop-limit?","a":"A stop-market order sends a market order when triggered and almost always fills. A stop-limit sends a limit order and only fills at your limit price or better."},{"q":"Why did my stop-limit order not execute?","a":"The price likely moved through your limit price too quickly, leaving your limit order unfilled in the book."},{"q":"How far should the limit be from the stop?","a":"It depends on the coin's volatility and liquidity. A wider gap raises the chance of a fill but allows a worse price."}],"title":"What is a stop-limit order? Meaning and example","description":"Learn how a stop-limit order works, how it differs from a stop-market order and why it may not fill in a crash.","related":[["stop-loss","Stop-loss order","A stop-loss order is an order that automatically closes your position when the price reaches a level you set, limiting how much you can lose on a trade."],["limit-order","Limit order","A limit order is an instruction to buy or sell only at a specific price or better, so a buy limit fills at your price or lower and a sell limit fills at your price or higher."],["slippage","Slippage","Slippage is the difference between the price you expect when you place a trade and the average price at which the trade actually fills, usually caused by thin liquidity or fast-moving markets."],["trailing-stop","Trailing stop","A trailing stop is a stop order that automatically follows the price at a set distance as it moves in your favour, then triggers if the price reverses by that distance."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Take-profit and stop-loss are plans, not insurance"},"coin":null,"tool":null,"cta":false},"time-in-force":{"slug":"time-in-force","cat":"trading","en":"Time in force (GTC, IOC, FOK)","contentLocale":"en","term":"Time in force (GTC, IOC, FOK)","aka":["TIF","GTC","IOC","FOK"],"short":"Time in force is an order setting that controls how long an order stays active and how it handles partial fills, with common options GTC (good till cancelled), IOC (immediate or cancel) and FOK (fill or kill).","body":["GTC is the default on most exchanges. The order stays in the book until it fills completely or you cancel it, though some platforms auto-expire very old orders. It is the right choice for patient limit orders.","IOC fills whatever it can immediately at your price or better and cancels the rest. If you want 10 coins and only 6 are available at your limit, you get 6 and the remaining 4 disappear instead of waiting. FOK is stricter: the entire order must fill immediately, or nothing fills at all.",["IOC and FOK are useful when you want an immediate result with price control, such as entering only if enough size is available, or ",["arbitrage","arbitrage"]," trades that only make sense at full size. Some exchanges also offer GTD (good till date) or post-only as a time-in-force option. Labels and choices vary, so check your order panel."]],"example":["Suppose the ask side shows 3 ",["BTC","bitcoin"]," at 64,000 and 2 BTC at 64,050 ",["USDT","usdt"],", and you send a buy limit for 4 BTC at 64,000. As GTC, you get 3 BTC now and 1 BTC waits in the book. As IOC, you get 3 BTC and the last 1 BTC is cancelled. As FOK, nothing fills, because only 3 BTC is available at 64,000 or better and the order needs all 4."],"mistakes":["Leaving old GTC orders open and forgetting about them until they fill unexpectedly.","Using FOK on a thin market and wondering why nothing ever fills.","Assuming IOC keeps the unfilled remainder in the book."],"faq":[{"q":"What does GTC mean in crypto trading?","a":"GTC means good till cancelled. The order stays open until it fills or you cancel it."},{"q":"What is the difference between IOC and FOK?","a":"IOC fills any available part immediately and cancels the rest. FOK fills the whole order immediately or cancels it entirely."},{"q":"Which time in force should beginners use?","a":"GTC for normal limit orders is usually fine. Just review your open orders regularly."}],"title":"Time in force: GTC, IOC and FOK meaning explained","description":"Learn what time in force means in crypto trading and how GTC, IOC and FOK orders handle partial fills.","related":[["limit-order","Limit order","A limit order is an instruction to buy or sell only at a specific price or better, so a buy limit fills at your price or lower and a sell limit fills at your price or higher."],["post-only-order","Post-only order","A post-only order is a limit order that is only allowed to add liquidity to the order book; if it would fill immediately against an existing order, the exchange cancels or adjusts it instead."],["market-order","Market order","A market order is an instruction to buy or sell immediately at the best price currently available in the order book, prioritising speed of execution over a specific price."],["order-book","Order book","An order book is the live list of all open buy orders (bids) and sell orders (asks) for a trading pair, sorted by price, showing how much people are willing to trade at each level."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Market, limit, cancel: what does each one solve?"},"coin":null,"tool":null,"cta":false},"private-key":{"slug":"private-key","cat":"wallets-security","en":"Private key","contentLocale":"en","term":"Private key","aka":["secret key"],"short":"A private key is a secret number that proves ownership of a crypto address and is used to sign transactions, so whoever holds it can spend the coins at that address.","body":[["In most blockchains, a private key is a 256-bit number, often shown as 64 hexadecimal characters. From it, the wallet calculates a ",["public key","public-key"],", and from the public key an address. This works in one direction only: you cannot work backwards from an address to the private key."],"When you send crypto, your wallet uses the private key to create a digital signature. The network checks the signature against your public key and accepts the transaction without ever seeing the key itself.",["Most people never handle raw private keys because wallets derive them from a ",["seed phrase","seed-phrase"],". Exporting a single private key is sometimes needed to import an account into another wallet, but it should be treated as carefully as the seed phrase."]],"example":["Picture a wallet with one ",["Ethereum","ethereum"]," address holding 0.8 ETH. You export its private key to import the account into a second wallet app and paste the key into a notes app that syncs to the cloud. Months later the cloud account is compromised. The attacker finds the 64-character key, imports it, and sends the 0.8 ETH away in one transaction. Your seed phrase was never exposed, yet that address is lost."],"mistakes":["Thinking a private key is safe to share because it is not the seed phrase.","Pasting a private key into a website that claims to check your balance or fix a stuck transaction.","Confusing the public address, which is safe to share, with the private key, which is not."],"faq":[{"q":"Can someone get my private key from my wallet address?","a":"No. Deriving the private key from an address is computationally infeasible with current technology."},{"q":"What is the difference between a private key and a public key?","a":"The private key signs and must stay secret. The public key and the address derived from it are shared so others can send you funds and verify your signatures."}],"title":"What is a private key in crypto? Meaning explained","description":"Learn what a private key is, how it signs transactions, how it relates to your address and seed phrase, and why it must stay secret.","related":[["seed-phrase","Seed phrase (recovery phrase)","A seed phrase is a list of usually 12 or 24 ordinary words that encodes the master key of a crypto wallet, so anyone who has the words can restore the wallet and spend all of its funds."],["public-key","Public key","A public key is the shareable half of a crypto key pair, calculated from the private key, that lets the network verify your signatures and from which your wallet address is derived."],["wallet-address","Wallet address","A wallet address is a string of letters and numbers that identifies where crypto can be sent on a specific blockchain, similar to an account number you can share publicly."],["multisig-wallet","Multisig wallet","A multisig wallet is a crypto wallet that needs signatures from several separate keys, such as 2 of 3, before any transaction can be sent, so no single lost or stolen key can move the funds."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Where are my coins? Exchange vs wallet"},"coin":null,"tool":null,"cta":false},"amm":{"slug":"amm","cat":"defi","en":"Automated market maker (AMM)","contentLocale":"en","term":"Automated market maker (AMM)","aka":["AMM","constant product market maker"],"short":"An automated market maker (AMM) is a type of DEX that prices trades with a mathematical formula based on the tokens held in a liquidity pool, instead of matching buyers and sellers in an order book.","body":["The best-known formula is the constant product, x times y equals k, used by Uniswap v2. A pool holds two tokens. When you buy one, you add the other, and the formula moves the price so that the product of the two balances stays the same, before fees.",[["Liquidity","liquidity"]," providers deposit both tokens and earn the trading fee. Bigger pools mean smaller price moves for the same trade, which is why large trades in shallow pools suffer heavy price impact."],["Newer designs adjust the model. Curve uses curves suited to assets that should trade near the same price, such as ",["stablecoins","stablecoin"],". Uniswap v3 and later let providers concentrate liquidity in a price range, which makes pools deeper near the current price but requires more active management."]],"example":["Suppose a pool holds 100 ",["ETH","ethereum"]," and 300,000 ",["USDC","usdc"],", so k is 30,000,000 and the price is 3,000 USDC per ETH. You buy ETH with 30,000 USDC, ignoring fees. The pool now has 330,000 USDC, so ETH must fall to 30,000,000 divided by 330,000, about 90.91 ETH. You receive about 9.09 ETH, an average price of roughly 3,300 USDC. That 10 percent gap is the price impact of a large trade in a small pool."],"mistakes":["Expecting the quoted spot price for a large trade in a small pool.","Thinking AMM liquidity providers only earn fees and never lose relative to holding.","Ignoring which AMM design a pool uses when comparing fees and depth."],"faq":[{"q":"How does an AMM set prices?","a":"By the ratio of tokens in the pool, adjusted through a formula. Arbitrage traders keep the pool price close to prices on other markets."},{"q":"Is Uniswap an AMM?","a":"Yes. Uniswap is one of the largest AMM-based decentralized exchanges."}],"title":"What is an AMM? Automated market maker explained","description":"How automated market makers price trades with a formula, why pool size drives price impact, and how AMM designs differ.","related":[["liquidity-pool","Liquidity pool","A liquidity pool is a smart contract holding two or more tokens that traders swap against on a DEX, funded by liquidity providers who earn a share of the trading fees."],["impermanent-loss","Impermanent loss","Impermanent loss is the shortfall a liquidity provider has compared with simply holding the same tokens, caused by the prices of the pooled tokens moving apart after the deposit."],["dex","Decentralized exchange (DEX)","A decentralized exchange (DEX) is a trading platform that runs on smart contracts, letting you swap tokens directly from your own wallet without depositing funds with a company."],["slippage","Slippage","Slippage is the difference between the price you expect when you place a trade and the average price at which the trade actually fills, usually caused by thin liquidity or fast-moving markets."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"staking":{"slug":"staking","cat":"defi","en":"Staking","contentLocale":"en","term":"Staking","aka":["crypto staking","stake"],"short":"Staking is locking up coins of a proof-of-stake blockchain to help validate transactions and secure the network, in return for staking rewards paid in that coin.","body":[["In proof-of-stake networks such as ",["Ethereum","ethereum"],", Solana and Cardano, validators put coins at stake as a guarantee of honest behaviour. They earn rewards from new issuance and transaction fees. If a ",["validator","validator"]," misbehaves or goes offline, some networks cut part of its stake, which is called slashing."],["You can stake in several ways: run your own validator, delegate to a validator, use a ",["liquid staking","liquid-staking"]," protocol that gives you a token like stETH, or use an exchange staking product where the platform runs the validators. Each route has different lock-up periods, fees and custody risk."],"Rewards are paid in the staked coin, so your value in dollars still depends on its price. Unstaking can take days or longer depending on the network, which matters if you might need to sell quickly."],"example":"Suppose you stake 10 SOL through a validator with an illustrative 7 percent annual reward and a 5 percent validator commission. Gross rewards for a year would be 0.7 SOL, the validator keeps 0.035 SOL, and you receive about 0.665 SOL. If SOL's price drops 30 percent during that year, your 10.665 SOL can still be worth less in dollars than the original 10 SOL was.","mistakes":["Counting staking rewards in coin terms only and forgetting the coin's price can fall.","Ignoring the unbonding or unstaking period before you need the funds.","Staking through an unknown site that asks you to send coins instead of delegating from your own wallet."],"faq":[{"q":"Is staking crypto safe?","a":"Native staking is generally lower-risk than many DeFi strategies, but you still face price risk, possible slashing and, with exchanges or protocols, platform risk."},{"q":"Can I lose my staked coins?","a":"You can lose some through slashing, smart contract failures or a platform failing, and their value can fall with the market."},{"q":"Are staking rewards taxed?","a":"In many countries they are, but rules differ on when and how. Check the tax rules where you live."}],"title":"What is staking in crypto? How rewards work","description":"Learn what crypto staking is, how proof-of-stake rewards and slashing work, and the different ways to stake.","related":[["proof-of-stake","Proof of stake (PoS)","Proof of stake (PoS) is a consensus mechanism in which validators lock up the network's coins as collateral to propose and confirm blocks, earning rewards for honest work and losing part of their stake for breaking the rules."],["liquid-staking","Liquid staking","Liquid staking is a way to stake coins through a protocol that issues a tradable token, such as stETH, representing your staked position, so you earn staking rewards and can still use or sell the token."],["validator","Validator","A validator is a participant in a proof-of-stake blockchain that locks up coins as collateral and runs software to propose new blocks and vote on whether other blocks are valid."],["crypto-earn","Crypto Earn (savings products)","Crypto Earn refers to exchange savings products that pay you a yield for depositing crypto, either flexible with withdrawal anytime or locked for a fixed term."],["apr-vs-apy","APR vs APY","APR is the simple annual rate of return or interest without compounding, while APY includes the effect of reinvesting earnings, so APY is higher than APR whenever returns compound."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":true},"total-value-locked":{"slug":"total-value-locked","cat":"defi","en":"Total value locked (TVL)","contentLocale":"en","term":"Total value locked (TVL)","aka":["TVL"],"short":"Total value locked (TVL) is the total market value of crypto deposited in a DeFi protocol or blockchain's smart contracts, used as a rough measure of its size and usage.","body":[["TVL adds up assets in pools, lending markets, ",["staking","staking"]," contracts and vaults, valued at current market prices. Data sites such as DefiLlama track TVL for protocols and for entire chains."],["Because it is measured in dollars, TVL rises and falls with token prices even if nobody deposits or withdraws. A protocol's TVL can drop 30 percent in a ",["market sell","market-order"],"-off with no change in users. TVL can also be inflated by counting the same assets twice, for example ",["ETH","ethereum"]," staked for an ",["LST","liquid-staking"]," that is then deposited elsewhere."],["TVL is useful for comparing size and ",["liquidity","liquidity"],", but it does not measure revenue, profit or safety. A high-TVL protocol can still be exploited, and rewards can attract short-lived deposits that leave when incentives end."]],"example":["Imagine a lending protocol holds 40,000 ETH at 2,500 ",["USDC","usdc"]," each and 150 million USDC in stablecoins. Its TVL is 40,000 times 2,500, which is 100 million, plus 150 million, for 250 million dollars. If ETH falls to 2,000 USDC, the ETH part drops to 80 million and TVL becomes 230 million, an 8 percent fall without anyone withdrawing."],"mistakes":["Reading a TVL drop as users leaving when it is mostly a price fall.","Treating high TVL as proof that a protocol is secure.","Comparing TVL across sites that count staked or borrowed assets differently."],"faq":[{"q":"Is a higher TVL better?","a":"It usually means more liquidity and usage, but it does not guarantee safety, sustainable revenue or good token performance."},{"q":"How is TVL different from market cap?","a":"Market cap values a token's supply. TVL values assets deposited in a protocol's contracts. They measure different things."}],"title":"What is TVL (total value locked) in DeFi?","description":"What total value locked means, how TVL is calculated, why it moves with prices, and its limits as a DeFi metric.","related":[["defi","DeFi (decentralized finance)","DeFi, short for decentralized finance, is a set of financial services such as trading, lending and earning yield that run on public blockchains through smart contracts instead of through banks or exchanges."],["liquidity-pool","Liquidity pool","A liquidity pool is a smart contract holding two or more tokens that traders swap against on a DEX, funded by liquidity providers who earn a share of the trading fees."],["defi-lending","DeFi lending","DeFi lending is borrowing and lending crypto through smart contracts, where lenders earn interest from a shared pool and borrowers must lock more collateral than they borrow."],["market-capitalization","Market capitalization","Market capitalization is the total value of a cryptocurrency's circulating coins, calculated as the current price multiplied by the circulating supply."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"depeg":{"slug":"depeg","cat":"stablecoins","en":"Depeg","contentLocale":"en","term":"Depeg","aka":["de-peg","stablecoin depeg","losing the peg"],"short":"A depeg is when a stablecoin or pegged token trades meaningfully away from the value it is designed to track, such as a dollar stablecoin falling below 1 USD.","body":[[["Stablecoins","stablecoin"]," like ",["USDT","usdt"]," and ",["USDC","usdc"]," aim to stay at 1 US dollar. Small moves such as 0.999 or 1.001 are normal market noise. A depeg means a larger or longer gap, usually because holders doubt the backing, redemptions are paused, or ",["liquidity","liquidity"]," on trading venues dries up."],["Causes differ by design. A fiat-backed coin can wobble if part of its reserves is stuck at a troubled bank. A crypto-backed coin can slip if its collateral crashes faster than liquidations can keep up. An algorithmic coin can collapse entirely when confidence breaks, because nothing hard backs it. Pegged tokens such as ",["liquid staking","liquid-staking"]," tokens can also trade at a discount when many holders rush to exit at once."],"For traders, a depeg matters in two ways: the stablecoin you count as cash may suddenly be worth less, and any position or loan priced in that coin can be repriced. Exchanges may also pause trading pairs, change margin rules or adjust collateral value during a depeg, and each one handles this differently."],"example":"Suppose you hold 10,000 units of a dollar stablecoin and news breaks that part of its reserves is frozen. The market price drops to 0.92 USD. On paper your balance is now worth 9,200 USD, a loss of 800 USD. If the issuer later restores full redemptions and the price returns to 1.00, the loss disappears. If it settles at 0.95 instead, the 500 USD gap becomes permanent for anyone who sold or still holds.","mistakes":["Treating every stablecoin as equally safe without checking what backs it and who can redeem it.","Panic selling into a thin market during a brief depeg and locking in a loss that would have recovered.","Buying a depegged coin as a sure bargain without understanding whether the backing can actually cover redemptions."],"faq":[{"q":"Can USDT or USDC depeg?","a":"Yes, any stablecoin can trade below its target. USDC briefly fell well below 1 USD in March 2023 when part of its reserves sat at a failed US bank, then recovered after the funds were confirmed safe."},{"q":"Does a depeg always mean the stablecoin is dead?","a":"No. Many depegs are short and recover once redemptions work again. A permanent depeg usually means the backing is insufficient or the design has failed."}],"title":"What is a depeg? Stablecoin depeg meaning","description":"Learn what a stablecoin depeg is, why stablecoins lose their dollar peg, and how a depeg affects your balance and open positions.","related":[["stablecoin","Stablecoin","A stablecoin is a cryptocurrency designed to keep a steady value, usually 1 US dollar, by being backed by reserves such as cash and treasury bills, by crypto collateral, or by other mechanisms."],["algorithmic-stablecoin","Algorithmic stablecoin","An algorithmic stablecoin is a stablecoin that tries to hold its peg mainly through code-driven supply changes and incentives rather than full reserves of cash or collateral."],["usdc","USDC","USDC is a US dollar stablecoin issued by Circle, designed to stay at 1 dollar and backed by cash and short-term US government securities, with monthly reserve attestations."],["liquid-staking","Liquid staking","Liquid staking is a way to stake coins through a protocol that issues a tradable token, such as stETH, representing your staked position, so you earn staking rewards and can still use or sell the token."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"Is USDT a dollar? Why is it everywhere when you buy crypto?"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":false},"real-world-assets":{"slug":"real-world-assets","cat":"tokenized-assets","en":"Real-world assets (RWA)","contentLocale":"en","term":"Real-world assets (RWA)","aka":["RWA","RWAs","tokenized real-world assets"],"short":"Real-world assets (RWA) are traditional assets such as bonds, gold, real estate, private credit or stocks represented as tokens on a blockchain.","body":[["RWA tokenization takes an off-chain asset, places it under the control of a legal entity or custodian, and issues tokens that represent a claim on it. The token can then move on-chain, be used in ",["DeFi protocols","defi"]," as collateral, or settle faster than traditional systems allow. Ondo Finance, BlackRock's BUIDL fund and Paxos Gold are well-known examples in this area."],["The largest categories are ",["tokenized US Treasuries","tokenized-treasuries"],", private credit, commodities such as gold, and ",["tokenized stocks","tokenized-stocks"],". Fiat-backed ",["stablecoins","stablecoin"]," are sometimes counted as RWAs too, since they are backed by off-chain reserves."],["Unlike native crypto, an RWA token depends on off-chain trust: the issuer, the custodian, the legal structure and the reliability of the data that brings prices on-chain. Many RWA products require ",["KYC","kyc"]," and are limited to certain investors or countries. Before buying, check what you actually own, how redemption works and who audits the reserves."]],"example":"Suppose a fund tokenizes 50,000,000 USD of short-term government bonds and issues 50,000,000 tokens at 1 USD each. The bonds yield 4% a year, and the fund charges 0.5%, so holders earn about 3.5%. If you hold 10,000 tokens for a year, you would earn about 350 USD, either as more tokens or a rising token price, depending on the product design.","mistakes":["Treating RWA tokens as risk-free because the underlying asset is traditional.","Ignoring the issuer, custodian and legal structure that the token depends on.","Assuming you can redeem directly when redemption may be limited to approved investors."],"faq":[{"q":"What does RWA mean in crypto?","a":"RWA stands for real-world assets, meaning traditional assets like bonds, gold or real estate represented by tokens on a blockchain."},{"q":"Are RWA tokens safe?","a":"They carry the asset's own risk plus issuer, custody, legal and smart contract risk. Safety depends on the specific structure and the parties behind it."}],"title":"What are real-world assets (RWA) in crypto?","description":"What real-world assets (RWA) are in crypto, how tokenization works, the main RWA categories and the off-chain risks behind them.","related":[["tokenized-treasuries","Tokenized treasuries","Tokenized treasuries are blockchain tokens that represent shares in a fund or vehicle holding short-term government bonds such as US Treasury bills, passing their yield to holders."],["tokenized-stocks","Tokenized stocks","Tokenized stocks are blockchain tokens designed to track the price of a company's shares, usually backed one to one by real shares held by a custodian."],["tokenized-gold","Tokenized gold","Tokenized gold is a blockchain token backed by physical gold held in a vault, where each token represents a set amount of gold, often one fine troy ounce."],["stablecoin","Stablecoin","A stablecoin is a cryptocurrency designed to keep a steady value, usually 1 US dollar, by being backed by reserves such as cash and treasury bills, by crypto collateral, or by other mechanisms."]],"lesson":null,"coin":{"slug":"ondo","name":"Ondo","symbol":"ONDO"},"tool":"/topics/tokenized-assets","cta":false}});
